import{_ as e,o as d,c as o,ag as r}from"./chunks/framework.HG0H2VLS.js";const g=JSON.parse('{"title":"Button — Figma Notes","description":"","frontmatter":{},"headers":[],"relativePath":"public/demos/src/components/Button/Button.figma-notes.md","filePath":"public/demos/src/components/Button/Button.figma-notes.md"}'),a={name:"public/demos/src/components/Button/Button.figma-notes.md"};function i(c,t,s,n,l,b){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="button-—-figma-notes" tabindex="-1">Button — Figma Notes <a class="header-anchor" href="#button-—-figma-notes" aria-label="Permalink to &quot;Button — Figma Notes&quot;">​</a></h1><h2 id="figma-node" tabindex="-1">Figma Node <a class="header-anchor" href="#figma-node" aria-label="Permalink to &quot;Figma Node&quot;">​</a></h2><p><strong>File:</strong> <code>Lus07xi8pPXLN87sQIyrEt</code> — Affino AI Design System <strong>Components page:</strong> node <code>1:769</code><strong>Button frame (all variants):</strong> node <code>53:2489</code></p><table tabindex="0"><thead><tr><th>Variant</th><th>Node ID</th></tr></thead><tbody><tr><td>Default (Primary) base</td><td><code>53:2488</code></td></tr><tr><td>Secondary base</td><td><code>53:2506</code></td></tr><tr><td>Tertiary base</td><td><code>57:1790</code></td></tr><tr><td>Tertiary Hover (text, base)</td><td><code>57:1794</code></td></tr><tr><td>Tertiary Hover (icon-only, base)</td><td><code>57:1848</code></td></tr><tr><td>Tertiary Focus (text, base)</td><td><code>57:1798</code></td></tr><tr><td>Tertiary Focus (icon-only, base)</td><td><code>57:1845</code></td></tr><tr><td>Alert base</td><td><code>60:2407</code></td></tr><tr><td>Alert Outline base (Default)</td><td><code>60:2423</code></td></tr><tr><td>Alert Outline base (Hover)</td><td><code>60:2426</code></td></tr><tr><td>Alert Outline base (Focus)</td><td><code>60:2429</code></td></tr><tr><td>Alert Outline base (Pressed)</td><td><code>60:2432</code></td></tr><tr><td>Icon Only (Default, base)</td><td><code>57:1809</code></td></tr></tbody></table><h2 id="variant-×-size-×-state-matrix" tabindex="-1">Variant × Size × State Matrix <a class="header-anchor" href="#variant-×-size-×-state-matrix" aria-label="Permalink to &quot;Variant × Size × State Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Sizes</th><th>States</th></tr></thead><tbody><tr><td>Default (Primary)</td><td>base, sm, xs</td><td>Default, Hover, Focus, Pressed, Disabled</td></tr><tr><td>Secondary</td><td>base, sm, xs</td><td>Default, Hover, Focus, Pressed, Disabled</td></tr><tr><td>Tertiary</td><td>base, sm, xs</td><td>Default, Hover, Focus, Pressed, Disabled</td></tr><tr><td>Alert</td><td>base, sm, xs</td><td>Default, Hover, Focus, Pressed</td></tr><tr><td>Alert Outline</td><td>base, sm, xs</td><td>Default, Hover, Focus, Pressed</td></tr><tr><td>Icon Only</td><td>base, sm, xs</td><td>Default, Hover, Focus, Pressed, Disabled</td></tr><tr><td>Icon Only</td><td><strong>2xs</strong> (code-only)</td><td>Default, Hover, Focus, Pressed, Disabled</td></tr></tbody></table><h2 id="css-class-mapping" tabindex="-1">CSS Class Mapping <a class="header-anchor" href="#css-class-mapping" aria-label="Permalink to &quot;CSS Class Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma Property</th><th>Values</th><th>CSS Class</th></tr></thead><tbody><tr><td><code>Type</code></td><td>Default</td><td><code>.btn--primary</code></td></tr><tr><td><code>Type</code></td><td>Secondary</td><td><code>.btn--secondary</code></td></tr><tr><td><code>Type</code></td><td>Tertiary</td><td><code>.btn--tertiary</code></td></tr><tr><td><code>Type</code></td><td>Alert</td><td><code>.btn--alert</code></td></tr><tr><td><code>Type</code></td><td>Alert Outline</td><td><code>.btn--alert-outline</code></td></tr><tr><td><code>Size</code></td><td>base</td><td><em>(none — default)</em></td></tr><tr><td><code>Size</code></td><td>sm</td><td><code>.btn--sm</code></td></tr><tr><td><code>Size</code></td><td>xs</td><td><code>.btn--xs</code></td></tr><tr><td><code>Size</code></td><td><em>(none — see below)</em></td><td><code>.btn--icon.btn--2xs</code></td></tr><tr><td><code>Icon Only</code></td><td>True</td><td><code>.btn--icon</code></td></tr><tr><td><code>State</code></td><td>Disabled</td><td><code>disabled</code> attr / <code>.btn--disabled</code></td></tr></tbody></table><h2 id="icon-slots-text-button-variants" tabindex="-1">Icon Slots (text-button variants) <a class="header-anchor" href="#icon-slots-text-button-variants" aria-label="Permalink to &quot;Icon Slots (text-button variants)&quot;">​</a></h2><p>Figma default for all text-button variants has <code>showLeftIcon=true</code> — both slots are visible.</p><table tabindex="0"><thead><tr><th>Slot</th><th>Placement</th><th>Default Lucide icon</th><th>HTML</th></tr></thead><tbody><tr><td>Left / leading</td><td>Before label text</td><td><code>chevron-right</code></td><td><code>&lt;i data-lucide=&quot;chevron-right&quot; aria-hidden=&quot;true&quot;&gt;&lt;/i&gt;</code></td></tr><tr><td>Right / trailing</td><td>After label text</td><td><code>arrow-right</code></td><td><code>&lt;i data-lucide=&quot;arrow-right&quot; aria-hidden=&quot;true&quot;&gt;&lt;/i&gt;</code></td></tr></tbody></table><ul><li><strong>Figma default (both icons):</strong> <code>&lt;i chevron-right&gt;</code> Label <code>&lt;i arrow-right&gt;</code> — use this in parent components unless Figma shows otherwise</li><li><strong>Icon-only buttons (<code>btn--icon</code>):</strong> single centred icon only, no left or right slot</li></ul><h2 id="token-mapping" tabindex="-1">Token Mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma Variable</th><th>CSS Variable</th><th>Role</th></tr></thead><tbody><tr><td><code>--ai-btn-primary-bg</code></td><td><code>--ai-btn-primary-bg</code></td><td>Primary bg</td></tr><tr><td><code>--ai-btn-primary-bg-hover</code></td><td><code>--ai-btn-primary-bg-hover</code></td><td>Primary hover + focus bg</td></tr><tr><td><code>--ai-btn-primary-bg-pressed</code></td><td><code>--ai-btn-primary-bg-pressed</code></td><td>Primary active bg</td></tr><tr><td><code>--ai-btn-primary-text</code></td><td><code>--ai-btn-primary-text</code></td><td>Primary text (theme-invariant)</td></tr><tr><td><code>--ai-btn-primary-text-hover</code></td><td><code>--ai-btn-primary-text-hover</code></td><td>Primary hover text</td></tr><tr><td><code>--ai-btn-secondary-bg</code></td><td><code>--ai-btn-secondary-bg</code></td><td>Secondary bg (transparent)</td></tr><tr><td><code>--ai-btn-secondary-bg-hover</code></td><td><code>--ai-btn-secondary-bg-hover</code></td><td>Secondary hover + focus bg</td></tr><tr><td><code>--ai-btn-secondary-bg-pressed</code></td><td><code>--ai-btn-secondary-bg-pressed</code></td><td>Secondary active bg</td></tr><tr><td><code>--ai-btn-secondary-border</code></td><td><code>--ai-btn-secondary-border</code></td><td>Secondary border (default + pressed + focus ring)</td></tr><tr><td><code>--ai-btn-secondary-border-hover</code></td><td><code>--ai-btn-secondary-border-hover</code></td><td>Secondary hover border</td></tr><tr><td><code>--ai-btn-secondary-text</code></td><td><code>--ai-btn-secondary-text</code></td><td>Secondary text</td></tr><tr><td><code>--ai-btn-secondary-text-hover</code></td><td><code>--ai-btn-secondary-text-hover</code></td><td>Secondary hover text</td></tr><tr><td><code>--ai-btn-tertiary-bg</code></td><td><code>--ai-btn-tertiary-bg</code></td><td>Tertiary bg (transparent); also focus bg</td></tr><tr><td><code>--ai-btn-tertiary-bg-hover</code></td><td><code>--ai-btn-tertiary-bg-hover</code></td><td>Tertiary hover bg</td></tr><tr><td><code>--ai-btn-tertiary-bg-pressed</code></td><td><code>--ai-btn-tertiary-bg-pressed</code></td><td>Tertiary active bg</td></tr><tr><td><code>--ai-btn-tertiary-text</code></td><td><code>--ai-btn-tertiary-text</code></td><td>Tertiary text</td></tr><tr><td><code>--ai-btn-tertiary-text-hover</code></td><td><code>--ai-btn-tertiary-text-hover</code></td><td>Tertiary hover text</td></tr><tr><td><code>--ai-btn-bg-disabled</code></td><td><code>--ai-btn-bg-disabled</code></td><td>Disabled bg (all variants)</td></tr><tr><td><code>--ai-btn-text-disabled</code></td><td><code>--ai-btn-text-disabled</code></td><td>Disabled text (all variants)</td></tr><tr><td><code>--ai-border-secondary</code></td><td><code>--ai-border-secondary</code></td><td>Tertiary focus ring</td></tr><tr><td><code>--ai-text-error</code></td><td><code>--ai-text-error</code></td><td>Alert Outline text</td></tr><tr><td><code>--ai-border-error</code></td><td><code>--ai-border-error</code></td><td>Alert Outline border</td></tr><tr><td><code>--ai-surface-error</code></td><td><code>--ai-surface-error</code></td><td>Alert bg (maps from Figma <code>Red/500</code>)</td></tr><tr><td><code>--ai-surface-primary</code></td><td><code>--ai-surface-primary</code></td><td>Alert Outline bg; inner border on primary/secondary focus</td></tr><tr><td><code>--ai-radius-md</code></td><td><code>--ai-radius-md</code></td><td>Default corner radius (8px)</td></tr><tr><td><code>--ai-radius-sm</code></td><td><code>--ai-radius-sm</code></td><td>Small button corner radius (4px)</td></tr><tr><td><code>--ai-spacing-8</code></td><td><code>--ai-spacing-8</code></td><td>Base height (40px)</td></tr><tr><td><code>--ai-spacing-7</code></td><td><code>--ai-spacing-7</code></td><td>Small height (32px)</td></tr><tr><td><code>--ai-font-fluid-xs</code></td><td><code>--ai-font-fluid-xs</code></td><td>Base font size (14px)</td></tr><tr><td><code>--ai-font-fluid-xxs</code></td><td><code>--ai-font-fluid-xxs</code></td><td>Small font size (12px)</td></tr><tr><td><code>--ai-leading-xs</code></td><td><code>--ai-leading-xs</code></td><td>Line height (16px)</td></tr><tr><td><code>--ai-icon-size-sm</code></td><td><code>--ai-icon-size-sm</code></td><td>Icon size inside base/sm buttons (16px)</td></tr><tr><td><code>--ai-icon-size-xs</code></td><td><code>--ai-icon-size-xs</code></td><td>Icon size inside xs buttons (12px)</td></tr><tr><td><code>--ai-spacing-2</code> / <code>--ai-spacing-3</code></td><td>same</td><td>xs vertical / horizontal padding (6px / 8px)</td></tr><tr><td><code>--ai-spacing-6</code></td><td><code>--ai-spacing-6</code></td><td>xs icon-only height (24px)</td></tr></tbody></table><h2 id="token-gaps-—-action-required-in-figma" tabindex="-1">Token Gaps — Action Required in Figma <a class="header-anchor" href="#token-gaps-—-action-required-in-figma" aria-label="Permalink to &quot;Token Gaps — Action Required in Figma&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Figma Primitive</th><th>Value</th><th>Token Needed</th><th>Affected Variants</th><th>Status</th></tr></thead><tbody><tr><td>Primary focus ring</td><td><code>--ai-surface-brand-light</code></td><td><code>#3a8fff</code></td><td>✓ resolved</td><td>Primary</td><td>✅ Implemented</td></tr><tr><td>Alert hover bg</td><td><code>Red/400</code></td><td><code>#f87171</code></td><td><code>--ai-btn-alert-hover</code></td><td>Alert, Alert Outline</td><td>✅ Primitive approved</td></tr><tr><td>Alert focus ring</td><td><code>Red/400</code></td><td><code>#f87171</code></td><td><code>--ai-btn-alert-focus-ring</code></td><td>Alert, Alert Outline</td><td>✅ Primitive approved</td></tr><tr><td>Alert pressed</td><td><code>Red/600</code></td><td><code>#dc2626</code></td><td><code>--ai-btn-alert-pressed</code></td><td>Alert</td><td>✅ Primitive approved</td></tr></tbody></table><p><strong>Note:</strong> Alert hover/pressed/focus states implemented using Figma primitives directly (approved). If semantic tokens are added to Figma in future, update <code>Button.css</code> to use <code>--ai-*</code> variables.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><code>button/base</code> typography: <code>--ai-font-fluid-xs</code> (14px), <code>--ai-font-semibold</code> (600), <code>--ai-leading-xs</code> (16px)</li><li><code>button/sm</code> typography: <code>--ai-font-fluid-xxs</code> (12px), <code>--ai-font-semibold</code> (600), <code>--ai-leading-xs</code> (16px)</li><li><code>button/xs</code> typography: <code>--ai-font-fluid-xxs</code> (12px), <code>--ai-font-medium</code> (500), <code>--ai-leading-xs</code> (16px). xs differs from sm: medium weight (not semibold), <code>--ai-radius-sm</code> (4px), <code>--ai-spacing-1</code> gap (4px), 12px icons (<code>--ai-icon-size-xs</code>), and explicit vertical padding (<code>--ai-spacing-2</code>) rather than a fixed-height token — 28px text / 24px icon-only have no spacing token, so xs uses Figma&#39;s <code>py-2</code> padding directly.</li><li>Secondary = <strong>transparent</strong> bg + <code>--ai-btn-secondary-border</code> (visually outlined)</li><li>Tertiary = <strong>transparent</strong> bg + <strong>no border</strong> (ghost/text button); uses dedicated <code>--ai-btn-tertiary-*</code> tokens</li><li>Tertiary hover bg: <code>--ai-btn-tertiary-bg-hover</code> (#F3F4F6); focus ring: <code>0 0 0 2px --ai-border-secondary</code> (no inner white border)</li><li>Secondary and tertiary now have dedicated token sets — no longer sharing <code>--ai-btn-secondary-*</code></li><li>Disabled: <code>--ai-btn-bg-disabled</code> for bg/border, <code>--ai-btn-text-disabled</code> for text (separate tokens)</li><li>Alert background uses Figma primitive <code>Red/500</code> → maps to <code>--ai-surface-error</code> (#ef4444)</li><li><code>.btn--lg</code> does <strong>not</strong> exist in Figma — removed from implementation</li><li>Figma exports the component collection key as <code>compnonents</code> (typo — do not fix in tokens)</li></ul><h2 id="btn-2xs-—-a-24x24-icon-size-that-leads-figma" tabindex="-1"><code>btn--2xs</code> — a 24x24 icon size that leads Figma <a class="header-anchor" href="#btn-2xs-—-a-24x24-icon-size-that-leads-figma" aria-label="Permalink to &quot;`btn--2xs` — a 24x24 icon size that leads Figma&quot;">​</a></h2><p>Added 2026-08-25 while building <strong>RoomCard</strong> (<code>3470:84951</code>), which places Button instances at <strong>24x24</strong> with a 12px icon. No existing size produces that:</p><table tabindex="0"><thead><tr><th>Size</th><th>Icon-only, as drawn in the Button set (<code>53:2489</code>)</th></tr></thead><tbody><tr><td>base</td><td>40x40</td></tr><tr><td>sm</td><td>32x32</td></tr><tr><td>xs</td><td>32x24 (Secondary/Tertiary), 28x24 (Primary)</td></tr><tr><td><strong>2xs</strong></td><td><strong>24x24 — does not exist in Figma</strong></td></tr></tbody></table><p>So RoomCard&#39;s buttons are <strong>resized instances</strong>, a Figma-side override rather than a variant. The designer chose to formalise the size in code (2026-08-25):</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.btn--icon.btn--2xs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { 24</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">x</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">24, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">padding</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 0, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">--ai-radius-sm</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, 12</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">px</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> icon</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>Two things to know about it:</p><ul><li><strong>It is icon-only on purpose.</strong> There is no text <code>.btn--2xs</code>, because Figma defines none, and inventing one would be a variant with no Figma counterpart. Writing <code>btn btn--2xs</code> without <code>btn--icon</code> therefore does nothing — the rule is a two-class combination, matching the house style of <code>.btn--icon.btn--sm</code> / <code>.btn--icon.btn--xs</code>.</li><li><strong>Its radius is set explicitly</strong>, unlike <code>--xs</code> which inherits <code>--ai-radius-sm</code> from the base <code>.btn--xs</code> rule. There is no base <code>.btn--2xs</code>, so nothing would carry it.</li><li>The icon rule targets <strong>both</strong> <code>[data-lucide]</code> and <code>svg</code>. <code>lucide.createIcons()</code> replaces the <code>&lt;i&gt;</code> with an <code>&lt;svg&gt;</code>, so an <code>[data-lucide]</code>-only selector is fragile. Verified 12x12 rendered.</li></ul><blockquote><p><strong>Figma follow-up:</strong> add a <code>Size=2xs</code> icon-only variant to the Button set so Figma and code agree, or resize RoomCard&#39;s instances to <code>xs</code>. Until then this row is code-ahead-of-Figma. <strong>Second consumer waiting:</strong> AttendeeCard&#39;s <code>.attendee-card__action</code> is the same geometry (24px box, 12px icon, <code>--ai-radius-sm</code>) built as scoped CSS — worth folding onto <code>btn--2xs</code>.</p></blockquote>',27)])])}const p=e(a,[["render",i]]);export{g as __pageData,p as default};
